    /**
     * If the current listbox supports multiselection.
     *
     * @type {boolean}
     */
    get isMultiselect() {
      return this.ariaMultiSelectable == "true";
    }

    connectedCallback() {
      if (this.hasConnected) {
        return;
      }
      this.hasConnected = true;

      this.setAttribute("is", "tree-listbox");

      switch (this.getAttribute("role")) {
        case "tree":
          this.isTree = true;
          break;
        case "listbox":
          this.isTree = false;
          break;
        default:
          throw new RangeError(`Unsupported role ${this.getAttribute("role")}`);
      }
      this.tabIndex = 0;

      this.domChanged();
      this._initRows();
      if (!this.selectedRow && this.rows.length) {
        // TODO: This should only really happen on "focus".
        this.updateSelection(this.getRowAtIndex(0));
      }

      this.addEventListener("click", this);
      this.addEventListener("keydown", this);
      this.addEventListener("keyup", this);
      this.addEventListener("blur", this);
      this.addEventListener("contextmenu", this);
      this._mutationObserver.observe(this, {
        subtree: true,
        childList: true,
      });
    }

    /**
     * If true, the "select" event dispatch is being deferred until keyup
     * because the user is holding a navigation key (typematic repeat).
     *
     * @type {boolean}
     */
    #selectEventDeferred = false;

